function initBuild(){const levels=BUILD_LEVELS.map(v=>`<option value="${v}">${v?`${v}级`:'未录入'}</option>`).join('');$('buildLevel').innerHTML=levels;$('buildEngine').innerHTML=levels;$('buildMindscape').innerHTML=BUILD_MINDSCAPES.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');$('buildSignature').innerHTML=BUILD_SIGNATURES.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');$('buildSkill').innerHTML=BUILD_SKILLS.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');$('buildDisc').innerHTML=BUILD_DISCS.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');$('buildLevel').onchange=e=>buildSet('level',Number(e.target.value));$('buildEngine').onchange=e=>buildSet('engine',Number(e.target.value));$('buildMindscape').onchange=e=>buildSet('mindscape',e.target.value==='unset'?'unset':Number(e.target.value));$('buildSignature').onchange=e=>buildSet('signature',e.target.value);$('buildSkill').onchange=e=>buildSet('skills',e.target.value);$('buildDisc').onchange=e=>buildSet('discs',e.target.value);$('buildMaxBtn').onclick=()=>{if(box.buildSlug)commitBoxChange(()=>{box.builds[box.buildSlug]=fullBuild(box.builds[box.buildSlug]||{});box.owned.add(box.buildSlug);});};$('buildClearBtn').onclick=()=>{if(box.buildSlug)commitBoxChange(()=>delete box.builds[box.buildSlug]);};}
function readBoxRaw(){for(const key of [BOX_KEY,...OLD_BOX_KEYS]){try{const text=localStorage.getItem(key);if(text)return JSON.parse(text);}catch{}}return{};}
