function loadBox(){try{applyBoxRaw(readBoxRaw());}catch{box.owned=new Set();box.builds={};box.buildSlug='';box.saveStatus='浏览器缓存';invalidateRecommendationBoxState();}boxUndoStack=[];}
function boxPayload(){const builds={};Object.entries(box.builds||{}).forEach(([rawSlug,build])=>{const slug=canonicalCharacterSlug(rawSlug);if(slug)builds[slug]=mergeBuildRecords(builds[slug],build);});Object.keys(builds).forEach(slug=>{if(!buildRecorded(builds[slug]))delete builds[slug];});return{version:3,updatedAt:new Date().toISOString(),owned:[...new Set([...box.owned].map(canonicalCharacterSlug).filter(Boolean))].sort(),buildSlug:canonicalCharacterSlug(box.buildSlug),builds};}
function enqueueBoxServerSave(pending){if(boxPendingSave===pending)boxPendingSave=null;const operation=boxSaveChain.catch(()=>undefined).then(()=>pending.revision===boxSaveRevision?saveBoxToServer(pending.payload,pending.revision):undefined);boxSaveChain=operation;operation.catch(()=>{});return operation;}
function saveBox(){const payload=boxPayload();box.exportStatus='';const exportButton=$('boxExportBtn');if(exportButton&&!exportButton.disabled){exportButton.textContent='导出Box';exportButton.title='';}clearTimeout(boxSaveTimer);boxSaveTimer=null;if(!desktopMode){localStorage.setItem(BOX_KEY,JSON.stringify(payload));boxPendingSave=null;OLD_BOX_KEYS.forEach(k=>localStorage.removeItem(k));box.saveStatus='已保存到浏览器';}else{const pending={payload,revision:++boxSaveRevision};boxPendingSave=pending;box.saveStatus='正在保存到本机';boxSaveTimer=setTimeout(()=>{boxSaveTimer=null;if(boxPendingSave===pending)boxPendingSave=null;enqueueBoxServerSave(pending).catch(()=>{});},180);}if(state.page==='box'||state.page==='banner')requestAnimationFrame(()=>{if(state.page==='box')renderBox();else renderBanner();});}
