globalThis.flushBoxSave=flushBoxSave;
function syncBoxFromServer(){return fetch('/api/zzz/box',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(new Error(`Box 读取失败（${r.status}）`))).then(server=>{server.fromServer=true;applyBoxRaw(server);boxUndoStack=[];localStorage.setItem(BOX_KEY,JSON.stringify(server));OLD_BOX_KEYS.forEach(k=>localStorage.removeItem(k));box.saveStatus='本机自动保存';});}
